import inspect
import json
import os
from datetime import datetime
from pathlib import Path
from typing import Optional

from ..exception import WrongDataFormat
from ..rp.client import ReportingPortalClient
from ..utils.encoder import BytesEncoder
from ..utils.logger import logger
from .creator import ReportCreator
from .testdata import SuiteData, TestData


class SingleReport:
    SINGLE_REPORT_PATH = "/home/ute/test_results/single_reports"

    def __init__(self, offline: Optional[bool] = False, skip_compression: Optional[bool] = False):
        self._test_data = TestData()
        self._suite_data = SuiteData()
        self._report_initialization_time = datetime.now().strftime(
            "%Y%m%d %H:%M:%S.000"
        )  # TODO pls dont
        self._offline_mode = offline
        self._skip_compression = skip_compression

    def report(self, **params):
        """Method used for reporting single test result using taf.sw.reporting_portal"""
        self._fill_test_data(**params)
        self._fill_suite_data(**params)
        self._set_start_and_endtime(**params)
        self._suite_data["result"] = SingleReport._normalize_result(
            result=params.get("result")
        )

        rp_link = self._pack_content_and_send()
        return rp_link

    @property
    def suite_data(self):
        return self._suite_data

    @property
    def test_data(self):
        return self._test_data

    @staticmethod
    def _format_report_time(report_time: str) -> str:
        """
        Reformat date stored in ``self._report_initialization_time`` to be more machine-friendly

        Example:
            '20221209 12:50:26.000' -> '20221209125026'
        """
        return datetime.strptime(report_time, "%Y%m%d %H:%M:%S.000").strftime(
            "%Y%m%d%H%M%S"
        )

    def _create_report_dir(self, report_time):
        report_time = self._format_report_time(report_time)
        report_path = os.path.join(
            SingleReport.SINGLE_REPORT_PATH,
            f"reporting_portal_report_{report_time}"
        )

        try:
            os.makedirs(report_path)
        except os.error as os_error_makedir:
            if os.path.exists(report_path):
                return report_path
            else:
                raise os_error_makedir

        return report_path

    def _fill_test_data(self, **test_parameters):
        _, _, _, local_vals = inspect.getargvalues(inspect.currentframe())
        if not local_vals["test_parameters"].get("qc_test_instance_name"):
            local_vals["test_parameters"]["qc_test_instance_name"] = local_vals[
                "test_parameters"
            ]["name"]

        for key, value in local_vals["test_parameters"].items():
            if key in self.test_data.keys() or key not in self._suite_data.keys():
                self.test_data[key] = value

    def _fill_suite_data(self, **suite_parameters):
        _, _, _, local_vals = inspect.getargvalues(inspect.currentframe())
        for key, value in local_vals["suite_parameters"].items():
            if key in self._suite_data:
                self._suite_data[key] = value
        self._suite_data["test_cases"].append(self.test_data)

    def _set_start_and_endtime(self, **params):
        start, end, now = (
            params.get("starttime"),
            params.get("endtime"),
            self._report_initialization_time,
        )
        self._suite_data["starttime"] = self.test_data["starttime"] = (
            start if start else now
        )
        self._suite_data["endtime"] = self.test_data["endtime"] = end if end else now

    def _pack_content_and_send(self):

        report_dir = self.__prepare_dirs_and_paths(self._report_initialization_time)
        self.__create_json(report_dir, self._report_initialization_time)

        zip_report = self.__create_zipfile(
            report_dir, timestamp=self._suite_data["starttime"]
        )

        if zip_report and not self._offline_mode:
            rp_client = ReportingPortalClient()

            response = rp_client.send_zip_report(zip_report)

            rp_link = response.save_link(
                os.path.join(report_dir, "reporting_portal_link.txt")
            )
            response.save_hash(os.path.join(report_dir, "reporting_portal_hash.txt"))

            return rp_link

    def __prepare_dirs_and_paths(self, report_time: str) -> str:
        return self._create_report_dir(report_time)

    def __create_zipfile(self, path: str, timestamp: str):
        zip_name = f"reporting_portal_{timestamp}.zip"
        creator = ReportCreator(zip_name)
        return creator.zip_directory(path, dst="/".join(path.split("/")[:-1]))

    def __create_json(self, dst, report_time):
        report_time = self._format_report_time(report_time)
        json_name = Path(dst) / f"reporting_portal_{report_time}.json"

        with json_name.open(mode="w") as json_file:
            json.dump([self.suite_data], json_file, cls=BytesEncoder)

        logger.debug(f"json file created: {json_name}")

        return json_name

    @staticmethod
    def _normalize_result(result):
        """Method used for normalizing results"""
        if str(result).lower() in ["true", "pass", "passed", "1"]:
            return "passed"
        elif str(result).lower() in ["false", "fail", "failed", "0"]:
            return "failed"
        else:
            raise WrongDataFormat(
                f"Wrong result value '{result}':\n"
                "Expected values:\n"
                "true, pass, passed, 1\n  or\nfalse, fail, failed, 0"
            )
